AttachmentCard: FC<AttachmentCardProps> = ({
  attachment,
  searchQuery = '',
  onRemove,
  onRetry,
  onExpand,
  onClick,
  onDownload,
  labels,
  styles: cardStyles,
  isSelected,
}) => {
  const { colors } = cardStyles ?? {};
  const isPasted = attachment.type === AttachmentType.Pasted;
  const isExpandable = isPasted && onExpand !== undefined;

  const cssVars = buildCssVars({
    '--ai-tile-bg': colors?.background,
    '--ai-tile-border': colors?.border,
    '--ai-tile-bg-hover': colors?.backgroundHover,
    '--ai-tile-border-hover': colors?.borderHover,
    '--ai-tile-bg-selected': colors?.backgroundSelected,
    '--ai-tile-border-selected': colors?.borderSelected,
    '--ai-tile-focus-outline': colors?.focusOutline,
    '--ai-tile-bg-error': colors?.backgroundError,
    '--ai-tile-border-error': colors?.borderError,
    '--ai-tile-error-text': colors?.errorText,
    '--ai-tile-name-text': colors?.nameText,
    '--ai-tile-type-text': colors?.typeText,
    '--ai-tile-hover-icon-bg': colors?.hoverIconBackground,
    '--ai-tile-hover-icon-color': colors?.hoverIconColor,
    '--ai-tile-progress-track': colors?.trackBackground,
  });

  const { isImage, isLink } = useMemo(
    () => getAttachmentCardState(attachment),
    [attachment],
  );

  if (isImage) {
    return (
      <ImageAttachment
        attachment={attachment}
        labels={labels}
        onClick={onClick}
        onExpand={onExpand}
        styles={cardStyles}
        onRemove={onRemove}
        cssVars={cssVars}
        onDownload={onDownload}
        isSelected={isSelected}
      />
    );
  }

  return (
    <FileAttachment
      attachment={attachment}
      searchQuery={searchQuery}
      onClick={onClick}
      onRetry={onRetry}
      onRemove={onRemove}
      onDownload={onDownload}
      isLink={isLink}
      isPasted={isPasted}
      styles={cardStyles}
      labels={labels}
      onExpand={onExpand}
      cssVars={cssVars}
      isExpandable={isExpandable}
      isSelected={isSelected}
    />
  );
}

AttachmentTray: FC<AttachmentTrayProps> = ({
  attachments,
  onRemove,
  onRetry,
  onExpand,
  onAttachmentClick,
  labels,
  styles,
}) => {
  const {
    ariaLabel = 'Attached files',
    removeLabel,
    retryLabel,
    clickLabel,
    uploadingLabel,
  } = labels ?? {};
  const { className } = styles ?? {};

  if (attachments.length === 0) return null;

  return (
    <div
      role="list"
      aria-label={ariaLabel}
      className={mergeClasses(
        'flex w-full min-w-0 gap-2 overflow-x-auto',
        className,
        ATTACHMENT_INPUT_CLASS.tray,
      )}
    >
      {attachments.map((attachment) => (
        <div
          key={attachment.id}
          role="listitem"
          className={ATTACHMENT_INPUT_CLASS.trayItem}
        >
          <AttachmentCard
            attachment={attachment}
            onRemove={onRemove}
            onRetry={onRetry}
            onExpand={onExpand}
            labels={{ removeLabel, retryLabel, clickLabel, uploadingLabel }}
            onClick={onAttachmentClick}
          />
        </div>
      ))}
    </div>
  );
}

AttachmentGroup: FC<AttachmentGroupProps> = ({
  attachments,
  onAttachmentClick,
  onDownloadAll,
  onRetry,
  labels,
  styles: groupStyles,
  selectedAttachmentId,
}) => {
  const {
    ariaLabel = 'Attachments',
    clickLabel = 'Download attachment',
    retryLabel = 'Retry upload',
    downloadAllLabel = 'Download all',
    openInNewTabLabel,
    getHeaderLabel = (count: number) => pluralize(count, 'attachment'),
    promptLabel,
    pastedLabel,
    imageLabel,
  } = labels ?? {};
  const { typography, colors, className } = groupStyles ?? {};
  const cssVars = buildCssVars({
    '--ai-group-text': colors?.text,
  });

  if (attachments.length === 0) return null;

  const hasImages = attachments.some((a) => a.type === AttachmentType.Image);
  const hasFiles = attachments.some((a) => a.type !== AttachmentType.Image);
  const isMixed = hasImages && hasFiles;
  const isCollapsible = attachments.length >= ATTACHMENT_COLLAPSE_THRESHOLD;

  const HeaderIcon = isMixed ? IconPaperclip : hasImages ? IconPhoto : IconFile;
  const headerLabel = getHeaderLabel(attachments.length);

  const handleDownloadAll = () => {
    /*
     * Skip attachments that individual tiles themselves wouldn't allow
     * downloading (still uploading, or failed) — "download all" must not
     * fire on a broken/incomplete attachment just because it's in the list.
     */
    const downloadableAttachments = attachments.filter(
      (attachment) => attachment.status === RequestStatus.Idle,
    );

    if (onDownloadAll) {
      onDownloadAll(downloadableAttachments);
    } else {
      downloadableAttachments.forEach((attachment) =>
        onAttachmentClick?.(attachment.id),
      );
    }
  };

  const handleDownload = (id: string) => {
    const downloadableAttachment = attachments.find(
      (attachment) => attachment.id === id,
    );
    if (downloadableAttachment) {
      onDownloadAll?.([downloadableAttachment]);
    }
  };

  return (
    <div
      role="group"
      aria-label={ariaLabel}
      style={cssVars}
      className={mergeClasses(
        'flex flex-col gap-1',
        isCollapsible ? 'w-full min-w-0 max-w-[492px]' : 'max-w-[420px]',
        styles.container,
        className,
      )}
    >
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-1">
          <HeaderIcon
            size={DIAL_ICON_SIZE.SM}
            className={mergeClasses('shrink-0', styles.headerIcon)}
            aria-hidden
          />
          <span
            className={mergeClasses(
              typography?.headerLabelClassName ?? 'dial-tiny-semi-text',
              styles.headerLabel,
            )}
          >
            {headerLabel}
          </span>
        </div>
        {attachments.length >= 2 && (onDownloadAll || onAttachmentClick) && (
          <GhostIconButton
            icon={
              <IconDownload
                size={DIAL_ICON_SIZE.SM}
                aria-hidden
                stroke={DIAL_KIT_ICON_STROKE}
              />
            }
            size={ElementSize.Small}
            aria-label={downloadAllLabel}
            onClick={handleDownloadAll}
          />
        )}
      </div>

      <div
        role="list"
        aria-label={headerLabel}
        className={mergeClasses(
          'gap-3',
          isCollapsible ? 'grid grid-cols-[repeat(5,83px)]' : 'flex flex-wrap',
        )}
      >
        {attachments.map((attachment, index) => (
          <div key={`${attachment.id}-${index}`} role="listitem">
            <AttachmentCard
              attachment={attachment}
              onClick={onAttachmentClick}
              onDownload={handleDownload}
              onRetry={onRetry}
              labels={{
                clickLabel,
                retryLabel,
                promptLabel,
                pastedLabel,
                imageLabel,
                openInNewTabLabel,
              }}
              isSelected={attachment.id === selectedAttachmentId}
            />
          </div>
        ))}
      </div>
    </div>
  );
}

FileDndOverlay: FC<FileDndOverlayProps> = ({
  isVisible,
  isAttachmentsAllowed = true,
  labels,
  styles: overlayStyles,
}) => {
  const { title, subtitle } = labels ?? {};
  const { colors, typography } = overlayStyles ?? {};

  if (!isVisible) return null;

  const cssVars = buildCssVars({
    '--ai-fd-bg': colors?.background,
    '--ai-fd-icon': colors?.icon,
    '--ai-fd-denied-icon': colors?.deniedIcon,
  });

  const resolvedTitle =
    title ?? (isAttachmentsAllowed ? 'Attach files' : 'No attachments allowed');
  const resolvedSubtitle =
    subtitle ??
    (isAttachmentsAllowed
      ? 'Drop files here to attach them to message'
      : "Attachments can't be added to message");
  const resolvedIconClassName = isAttachmentsAllowed
    ? styles.icon
    : styles.deniedIcon;

  const suppressDrop = (e: DragEvent) => {
    e.preventDefault();
  };

  const Icon = isAttachmentsAllowed ? IconFileDescription : IconFileX;

  return (
    <div
      role="status"
      aria-live="polite"
      className={mergeClasses(
        'fixed inset-0 z-[9999] flex items-center justify-center backdrop-blur-sm',
        styles.overlay,
        isAttachmentsAllowed
          ? 'pointer-events-none'
          : 'pointer-events-auto cursor-not-allowed',
      )}
      onDragOver={isAttachmentsAllowed ? undefined : suppressDrop}
      onDrop={isAttachmentsAllowed ? undefined : suppressDrop}
      style={cssVars}
    >
      <div className="flex flex-col items-center text-center">
        <Icon size={100} className={resolvedIconClassName} aria-hidden />
        <span
          className={mergeClasses(
            'mt-5',
            typography?.titleClassName ?? 'dial-h3-text',
          )}
        >
          {resolvedTitle}
        </span>
        <span
          className={mergeClasses(
            'mt-4',
            typography?.subtitleClassName ?? 'dial-small-text',
          )}
        >
          {resolvedSubtitle}
        </span>
      </div>
    </div>
  );
}

export interface AttachmentCardProps {
  /** The attachment data to display. */
  attachment: DisplayAttachment;
  /** Current search query — when set, matches in the file name are highlighted. Defaults to `''`. */
  searchQuery?: string;
  /** Called when the user activates the remove button. */
  onRemove?: (id: string) => void;
  /** Called when the user activates the retry button (error state only). */
  onRetry?: (id: string) => void;
  /** Called when the user clicks or activates a pasted-text card to expand its content back into the input. */
  onExpand?: (id: string) => void;
  /** Called when the user clicks or keyboard-activates the card. Receives the attachment `id`. */
  onClick?: (id: string) => void;
  /** Localised accessible labels for the remove/retry actions, the interactive card root, and the non-extension attachment type names (prompt/pasted/image). */
  labels?: AttachmentCardLabels;
  /** Color, typography, and shape overrides for the card. */
  styles?: AttachmentCardStyles;
  /** Called when the user activates the download button. Receives the attachment `id`. */
  onDownload?: (id: string) => void;
  /** Whether this attachment is the one currently open in the canvas panel. Renders the tile's selected visual state. */
  isSelected?: boolean;
}

export interface AttachmentCardColors {
  /** Tile background color in the default state. */
  background?: string;
  /** Tile border color in the default state. */
  border?: string;
  /** Tile background color on hover. */
  backgroundHover?: string;
  /** Tile border color on hover. */
  borderHover?: string;
  /** Tile background color in the selected state. */
  backgroundSelected?: string;
  /** Tile border color in the selected state. */
  borderSelected?: string;
  /** Tile focus outline color. */
  focusOutline?: string;
  /** Tile background color in the error state. */
  backgroundError?: string;
  /** Tile border color in the error state. */
  borderError?: string;
  /** File name/type text color in the error state. */
  errorText?: string;
  /** File name text color. */
  nameText?: string;
  /** Type/meta text color. */
  typeText?: string;
  /** Hover download icon background color. */
  hoverIconBackground?: string;
  /** Hover download icon color. */
  hoverIconColor?: string;
  /** Upload progress track background color. */
  trackBackground?: string;
}

export interface AttachmentCardTypography {
  /** Utility class applied to the file name text. Defaults to `'dial-tiny-text'`. */
  fontClassName?: string;
  /** Utility class applied to the bottom meta label (file type / status). Defaults to `'dial-caption-text'`. */
  metaClassName?: string;
}

export interface AttachmentCardStyles {
  /** Color overrides applied as CSS custom properties. */
  colors?: AttachmentCardColors;
  /** Typography overrides for text elements inside the card. */
  typography?: AttachmentCardTypography;
  /** Extra class name(s) merged onto the root element. */
  className?: string;
}

export interface AttachmentCardLabels extends AttachmentTypeLabels {
  /** Accessible label for the remove button. Defaults to `'Remove attachment'`. */
  removeLabel?: string;
  /** Accessible label for the retry button (error state only). Defaults to `'Retry upload'`. */
  retryLabel?: string;
  /** Accessible label applied to the card root when it is interactive via `onClick`. Defaults to `'Open attachment'`. */
  clickLabel?: string;
  /** Accessible label applied to the card root when it is interactive via `onExpand` (pasted-text cards). Defaults to `'Expand pasted text'`. */
  expandLabel?: string;
  /** Accessible label for the loading spinner shown while the attachment is uploading. Defaults to `'Loading attachment'`. */
  loadingLabel?: string;
  /** Accessible label for the file card's in-progress upload progress bar. Defaults to `'Uploading'`. */
  uploadingLabel?: string;
  /** Accessible label for the download button. Defaults to `'Download attachment'`. */
  downloadLabel?: string;
  /** Accessible label for the open-in-new-tab button. Defaults to `'Open in new tab'`. */
  openInNewTabLabel?: string;
}

export interface AttachmentCardState {
  /** Whether the attachment is currently uploading. */
  isLoading: boolean;
  /** Whether the attachment's upload failed. */
  isError: boolean;
  /** Whether the attachment should render as a previewable image tile. */
  isImage: boolean;
  /** Whether the attachment should render as a link tile. */
  isLink: boolean;
  /** Icon component representing the attachment's type. */
  BottomIcon: Icon | null;
  /** Human-readable type/status label rendered next to `BottomIcon`. */
  typeLabel: string | null;
}

export interface AttachmentTypeLabels {
  /** Label shown for a prompt-type attachment. Defaults to `'Prompt'`. */
  promptLabel?: string;
  /** Label shown for a pasted-text attachment. Defaults to `'Pasted'`. */
  pastedLabel?: string;
  /** Label shown for an image attachment. Defaults to `'Image'`. */
