useClipboardPaste = (
  onAttachments: (attachments: Attachment[]) => void,
  threshold: number,
  labels: UseClipboardPasteLabels = {},
): { handlePaste: ClipboardEventHandler<HTMLTextAreaElement> } => {
  const { screenshotName = 'Screenshot.png', pastedTextName = 'Pasted text' } =
    labels;

  const handlePaste: ClipboardEventHandler<HTMLTextAreaElement> = useCallback(
    (event) => {
      if (!event.clipboardData) return;

      const items = Array.from(event.clipboardData.items);
      const imageItems = items.filter(
        (item) => item.kind === 'file' && item.type.startsWith('image/'),
      );
      const hasText = event.clipboardData.getData('text/plain').length > 0;

      if (imageItems.length > 0 && !hasText) {
        const imageAttachments: Attachment[] = [];
        const pastedAt = new Date();
        for (const item of imageItems) {
          const blob = item.getAsFile();
          if (!blob) continue;
          const name = buildPastedImageName(
            screenshotName,
            pastedAt,
            imageAttachments.length,
          );
          const file = new File([blob], name, {
            type: blob.type,
          });
          const attachment: Attachment = {
            id: generateAttachmentId(),
            name,
            contentType: blob.type,
            file,
            type: AttachmentType.Image,
            status: RequestStatus.Idle,
            previewUrl: URL.createObjectURL(file),
          };
          imageAttachments.push(attachment);
        }
        event.preventDefault();
        onAttachments(imageAttachments);
        return;
      }

      const text = event.clipboardData.getData('text/plain');
      if (text.length > threshold) {
        const trimmed = text.trim();
        const MAX_PREVIEW = 80;
        const preview =
          trimmed.length > MAX_PREVIEW
            ? `${trimmed.slice(0, MAX_PREVIEW).trimEnd()}…`
            : trimmed;
        const fileName = preview || pastedTextName;
        const file = new File([text], fileName, {
          type: 'text/plain',
        });
        const pastedAttachment: Attachment = {
          id: generateAttachmentId(),
          name: fileName,
          contentType: 'text/plain',
          file,
          type: AttachmentType.Pasted,
          status: RequestStatus.Idle,
        };
        event.preventDefault();
        onAttachments([pastedAttachment]);
      }
    },
    [onAttachments, threshold, screenshotName, pastedTextName],
  );

  return { handlePaste };
}

