  const resolvedSubtitle =
    subtitle ??
    (isAttachmentsAllowed
      ? 'Drop files here to attach them to message'
      : "Attachments can't be added to message");
  const resolvedIconClassName = isAttachmentsAllowed
    ? styles.icon
    : styles.deniedIcon;

  const suppressDrop = (e: DragEvent) => {
    e.preventDefault();
  };

  const Icon = isAttachmentsAllowed ? IconFileDescription : IconFileX;

  return (
    <div
      role="status"
      aria-live="polite"
      className={mergeClasses(
        'fixed inset-0 z-[9999] flex items-center justify-center backdrop-blur-sm',
        styles.overlay,
        isAttachmentsAllowed
          ? 'pointer-events-none'
          : 'pointer-events-auto cursor-not-allowed',
      )}
      onDragOver={isAttachmentsAllowed ? undefined : suppressDrop}
      onDrop={isAttachmentsAllowed ? undefined : suppressDrop}
      style={cssVars}
    >
      <div className="flex flex-col items-center text-center">
        <Icon size={100} className={resolvedIconClassName} aria-hidden />
        <span
          className={mergeClasses(
            'mt-5',
            typography?.titleClassName ?? 'dial-h3-text',
          )}
        >
          {resolvedTitle}
        </span>
        <span
          className={mergeClasses(
            'mt-4',
            typography?.subtitleClassName ?? 'dial-small-text',
          )}
        >
          {resolvedSubtitle}
        </span>
      </div>
    </div>
  );
}

useClipboardPaste = (
  onAttachments: (attachments: Attachment[]) => void,
  threshold: number,
  labels: UseClipboardPasteLabels = {},
): { handlePaste: ClipboardEventHandler<HTMLTextAreaElement> } => {
  const { screenshotName = 'Screenshot.png', pastedTextName = 'Pasted text' } =
    labels;

  const handlePaste: ClipboardEventHandler<HTMLTextAreaElement> = useCallback(
    (event) => {
      if (!event.clipboardData) return;

      const items = Array.from(event.clipboardData.items);
      const imageItems = items.filter(
        (item) => item.kind === 'file' && item.type.startsWith('image/'),
      );
      const hasText = event.clipboardData.getData('text/plain').length > 0;

      if (imageItems.length > 0 && !hasText) {
        const imageAttachments: Attachment[] = [];
        const pastedAt = new Date();
        for (const item of imageItems) {
          const blob = item.getAsFile();
          if (!blob) continue;
          const name = buildPastedImageName(
            screenshotName,
            pastedAt,
            imageAttachments.length,
          );
          const file = new File([blob], name, {
            type: blob.type,
          });
          const attachment: Attachment = {
            id: generateAttachmentId(),
            name,
            contentType: blob.type,
            file,
            type: AttachmentType.Image,
            status: RequestStatus.Idle,
            previewUrl: URL.createObjectURL(file),
          };
          imageAttachments.push(attachment);
        }
        event.preventDefault();
        onAttachments(imageAttachments);
        return;
      }

      const text = event.clipboardData.getData('text/plain');
      if (text.length > threshold) {
        const trimmed = text.trim();
        const MAX_PREVIEW = 80;
        const preview =
          trimmed.length > MAX_PREVIEW
            ? `${trimmed.slice(0, MAX_PREVIEW).trimEnd()}…`
            : trimmed;
        const fileName = preview || pastedTextName;
        const file = new File([text], fileName, {
          type: 'text/plain',
        });
        const pastedAttachment: Attachment = {
          id: generateAttachmentId(),
          name: fileName,
          contentType: 'text/plain',
          file,
          type: AttachmentType.Pasted,
          status: RequestStatus.Idle,
        };
        event.preventDefault();
        onAttachments([pastedAttachment]);
      }
    },
    [onAttachments, threshold, screenshotName, pastedTextName],
  );

  return { handlePaste };
}

useLazyImageLoad = ({
  enabled,
  src,
}: UseLazyImageLoadParams): {
  imageRef: RefObject<HTMLImageElement | null>;
  imageLoadStatus: LazyImageLoadStatus;
} => {
  const imageRef = useRef<HTMLImageElement>(null);
  const [imageLoadStatus, setImageLoadStatus] = useState<LazyImageLoadStatus>(
    LazyImageLoadStatus.Idle,
  );

  useEffect(() => {
    setImageLoadStatus(
      enabled && src ? LazyImageLoadStatus.Loading : LazyImageLoadStatus.Idle,
    );
  }, [enabled, src]);

  useEffect(() => {
    const imageElement = imageRef.current;
    if (!imageElement || !enabled || !src) {
      return;
    }

    const handleImageLoad = (): void =>
      setImageLoadStatus(LazyImageLoadStatus.Loaded);
    const handleImageError = (): void =>
      setImageLoadStatus(LazyImageLoadStatus.Error);

    imageElement.addEventListener('load', handleImageLoad);
    imageElement.addEventListener('error', handleImageError);

    if (imageElement.complete) {
      setImageLoadStatus(
        imageElement.naturalWidth > 0
          ? LazyImageLoadStatus.Loaded
          : LazyImageLoadStatus.Error,
      );
    }

    return () => {
      imageElement.removeEventListener('load', handleImageLoad);
      imageElement.removeEventListener('error', handleImageError);
    };
  }, [enabled, src]);

  return { imageRef, imageLoadStatus };
}

getAttachmentCardState = (
  attachment: DisplayAttachment,
  typeLabels: AttachmentTypeLabels = {},
): AttachmentCardState => {
  const { type, status, previewUrl, url } = attachment;

  const isLoading = status === RequestStatus.Loading;
  const isError = status === RequestStatus.Error;
  const isImage =
    type === AttachmentType.Image && !!(previewUrl ?? url) && !isError;
  const isLink = type === AttachmentType.Link && !isError;

  return {
    isLoading,
    isError,
    isImage,
    isLink,
    BottomIcon: isLink ? null : getBottomIcon(attachment),
    typeLabel: isLink ? null : getBottomLabel(attachment, typeLabels),
  };
}

getExtFromContentType = (
  contentType: string,
): string | undefined => {
  const mime = contentType.toLowerCase().split(';')[0].trim();
  const override = MIME_TYPE_EXT_MAP[mime];
  if (override) return override;
  const subtype = mime.split('/')[1];
  // Skip complex vendor/structured subtypes (e.g. vnd.openxmlformats-..., svg+xml)
  if (subtype && !subtype.startsWith('vnd.') && !subtype.includes('+')) {
    return subtype;
  }
  return undefined;
}

getAttachmentIcon = (contentType: string): Icon => {
  if (!contentType) return IconFile;
  // Broad category checks first
  if (contentType.startsWith('image/')) {
    switch (contentType) {
      case 'image/jpeg':
      case 'image/jpg':
        return IconFileTypeJpg;
      case 'image/png':
        return IconFileTypePng;
      case 'image/svg+xml':
        return IconFileTypeSvg;
      case 'image/bmp':
        return IconFileTypeBmp;
      default:
        return IconPhoto;
    }
  }

  if (contentType.startsWith('video/')) return IconVideo;
  if (contentType.startsWith('audio/')) return IconMusic;

  // Specific MIME type switch
  switch (contentType) {
    // Documents
    case 'application/pdf':
      return IconFileTypePdf;
    case 'application/msword':
    case 'application/vnd.ms-word':
      return IconFileTypeDoc;
    case 'application/vnd.openxmlformats-officedocument.wordprocessingml.document':
      return IconFileTypeDocx;
    case 'application/vnd.ms-powerpoint':
      return IconFileTypePpt;
    case 'application/vnd.openxmlformats-officedocument.presentationml.presentation':
      return IconFileTypePpt;
    case 'application/vnd.ms-excel':
      return IconFileTypeXls;
    case 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet':
      return IconFileTypeXls;

    // Archives
    case 'application/zip':
    case 'application/x-zip-compressed':
    case 'application/x-rar-compressed':
    case 'application/x-7z-compressed':
    case 'application/gzip':
    case 'application/x-tar':
      return IconFileTypeZip;

    // Data / markup
    case 'text/csv':
      return IconFileTypeCsv;
    case 'text/plain':
      return IconFileTypeTxt;
    case 'text/html':
    case 'application/xhtml+xml':
      return IconFileTypeHtml;
    case 'text/xml':
    case 'application/xml':
      return IconFileTypeXml;
    case 'application/sql':
    case 'text/x-sql':
      return IconFileTypeSql;

    // Web / code
    case 'text/javascript':
    case 'application/javascript':
      return IconFileTypeJs;
    case 'text/jsx':
      return IconFileTypeJsx;
    case 'application/typescript':
    case 'text/typescript':
      return IconFileTypeTs;
    case 'text/tsx':
      return IconFileTypeTsx;
    case 'text/css':
      return IconFileTypeCss;
    case 'text/x-php':
    case 'application/x-php':
      return IconFileTypePhp;
    case 'text/x-rustsrc':
    case 'application/x-rust':
      return IconFileTypeRs;
    case 'text/x-vue':
      return IconFileTypeVue;

    default:
      return IconFile;
  }
}

